import type { ActivityGrid as Grid, DayPost, GridCell } from '@emberly/core';
import { useMemo, useRef, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, View, type ScrollViewInstance } from 'react-native';
import { useTheme } from '@/lib/theme';
import { Txt } from './ui';

const CELL = 13;
const GAP = 4;

/**
 * Native activity grid: weeks scroll horizontally (newest visible first),
 * tapping a day shows its details below. Each day carries the same
 * accessibility label the web uses, generated by @emberly/core.
 */
export function ActivityGrid({ grid, dayPosts, today }: { grid: Grid; dayPosts: Record<string, DayPost[]>; today: string }) {
  const t = useTheme();
  const scroller = useRef<ScrollViewInstance>(null);
  const todayCell = useMemo(() => grid.weeks.flat().find((c) => c.date === today) ?? null, [grid, today]);
  const [selected, setSelected] = useState<GridCell | null>(todayCell);
  const monthAt = useMemo(() => new Map(grid.months.map((m) => [m.column, m.label])), [grid]);

  const fill = (c: GridCell) => {
    if (c.state === 'untracked' || (c.state === 'rest' && c.count === 0)) return 'transparent';
    if (c.state === 'paused' && c.count === 0) return t.duskSoft;
    return t.grid[c.level];
  };

  const posts = selected ? (dayPosts[selected.date] ?? []) : [];

  return (
    <View style={{ gap: 12 }}>
      <ScrollView ref={scroller} horizontal showsHorizontalScrollIndicator={false} onContentSizeChange={() => scroller.current?.scrollToEnd({ animated: false })}>
        <View style={{ flexDirection: 'row', gap: GAP }}>
          {grid.weeks.map((week, col) => (
            <View key={week[0]!.date} style={{ gap: GAP }}>
              <Txt tone="small" style={styles.month} numberOfLines={1}>
                {monthAt.get(col) ?? ''}
              </Txt>
              {week.map((c) =>
                c.state === 'future' ? (
                  <View key={c.date} style={styles.cell} importantForAccessibility="no" />
                ) : (
                  <Pressable
                    key={c.date}
                    onPress={() => setSelected(c)}
                    accessibilityRole="button"
                    accessibilityLabel={c.label}
                    accessibilityState={{ selected: selected?.date === c.date }}
                    hitSlop={2}
                    style={[
                      styles.cell,
                      { backgroundColor: fill(c) },
                      (c.state === 'rest' || c.state === 'untracked') && c.count === 0 ? { borderWidth: 1, borderColor: t.lineStrong } : null,
                      c.goalMet ? { borderWidth: 1.5, borderColor: t.sage } : null,
                      selected?.date === c.date ? { borderWidth: 2, borderColor: t.accent } : null,
                    ]}
                  />
                ),
              )}
            </View>
          ))}
        </View>
      </ScrollView>

      <View style={styles.legend} accessibilityLabel={`Legend: ${grid.buckets.map((b) => b.label).join(', ')}`}>
        <Txt tone="small">Less</Txt>
        {[0, 1, 2, 3, 4].map((l) => (
          <View key={l} style={[styles.cell, { backgroundColor: t.grid[l] }]} />
        ))}
        <Txt tone="small">More · tap a day</Txt>
      </View>

      {selected ? (
        <View style={[styles.detail, { borderTopColor: t.line }]} accessibilityLiveRegion="polite">
          <Txt style={{ fontWeight: '600' }}>{selected.label}</Txt>
          {posts.slice(0, 4).map((p) => (
            <Txt key={p.id} tone="small" numberOfLines={1}>
              {p.time} · {p.preview ?? p.kind}
              {p.reactions != null ? ` · ${p.reactions} reactions` : ''}
            </Txt>
          ))}
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  cell: { width: CELL, height: CELL, borderRadius: 5 },
  month: { height: 16, width: CELL, overflow: 'visible', fontSize: 10 },
  legend: { flexDirection: 'row', alignItems: 'center', gap: 6, flexWrap: 'wrap' },
  detail: { borderTopWidth: StyleSheet.hairlineWidth, paddingTop: 10, gap: 4 },
});
